svg.script:
(function(){
  const modules = Array.from(document.querySelectorAll('.module'));
  const tooltip = document.getElementById('tooltip');
  const title = document.getElementById('tooltip-title');
  const notes = document.getElementById('tooltip-notes');
  const attrs = document.getElementById('tooltip-attrs');
  function clear(){modules.forEach((node)=>node.classList.remove('is-source','is-dependency'));}
  function activate(node){
    clear();
    node.classList.add('is-source');
    String(node.dataset.deps||'').split(/\s+/).filter(Boolean).forEach((id)=>{const dep=document.getElementById(id);if(dep)dep.classList.add('is-dependency');});
  }
  modules.forEach((node)=>{
    node.addEventListener('mouseenter',()=>activate(node));
    node.addEventListener('focus',()=>activate(node));
    node.addEventListener('mouseleave',clear);
    node.addEventListener('blur',clear);
    node.addEventListener('click',(event)=>{
      event.stopPropagation();
      title.textContent=node.dataset.title||'Module';
      notes.textContent=node.dataset.notes||'';
      attrs.textContent=node.dataset.attributes||'';
      tooltip.classList.add('visible');
      tooltip.setAttribute('aria-hidden','false');
    });
  });
  document.addEventListener('click',()=>{tooltip.classList.remove('visible');tooltip.setAttribute('aria-hidden','true');clear();});
}());
